def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_budgets = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    richest_opp = max(opp_budgets) if opp_budgets else 0.0

    severe = (hp <= 3) or (no_water >= 2)
    urgent = (hp <= 5) or (no_water >= 1)
    scarce = supply <= 18
    comfortable_budget = budget >= richest_opp * 0.8 or budget >= 700

    if severe:
        target = max(DAILY_SALARY * 1.35, highest_prev + 3.0)
        if comfortable_budget and scarce:
            target = max(target, DAILY_SALARY * 1.55)
        return float(min(budget, target))

    if urgent:
        if highest_prev >= 150:
            target = DAILY_SALARY * 0.92 if not scarce else DAILY_SALARY * 1.08
        elif highest_prev >= 100:
            target = max(DAILY_SALARY * 0.82, highest_prev + 2.0)
        else:
            target = DAILY_SALARY * 0.78 if scarce else DAILY_SALARY * 0.68
        return float(min(budget, target))

    if scarce:
        if highest_prev >= 140:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= 100:
            target = DAILY_SALARY * 0.42
        else:
            target = max(DAILY_SALARY * 0.48, avg_prev * 0.7)
    else:
        if highest_prev >= 140:
            target = DAILY_SALARY * 0.22
        elif highest_prev >= 100:
            target = DAILY_SALARY * 0.34
        else:
            target = DAILY_SALARY * 0.4

    if budget < 250:
        target = min(target, DAILY_SALARY * 0.45)

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # If no budget, bid 0
    if my_status['budget'] <= 0:
        return 0.0

    # Consider only alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        # No competition: bid minimal to get water if possible
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    # Extract yesterday bids from previous_trace (immediate reaction)
    prev_bids = []
    prev_by_id = {}
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                b_val = None
            if b_val is not None:
                prev_bids.append(b_val)
                prev_by_id[opp_id] = b_val

    # Determine pressure level from yesterday
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # If Cindy exists and had high yesterday bid, treat as main pressure
    main_pressure = 0.0
    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive', False):
        prev = opponents_status['Cindy'].get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                main_pressure = float(b)
            except Exception:
                main_pressure = 0.0

    # Supply-based aggressiveness: when supply is higher, we can bid less and still likely win.
    # Normalize supply in [MIN_SUPPLY, MAX_SUPPLY]
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.6
    else:
        supply_factor = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # HP urgency
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    urgency = 0.0
    if hp <= 1.5:
        urgency = 1.0
    elif hp <= 3.0:
        urgency = 0.75
    elif hp <= 5.0:
        urgency = 0.5
    else:
        urgency = 0.25

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Target bid logic:
    # - If Cindy bid was very high yesterday, bid moderately high to contest.
    # - Otherwise, bid around a fraction of DAILY_SALARY, scaled by urgency and supply.
    base = DAILY_SALARY * 0.45

    # Contest multiplier based on yesterday pressure
    contest = 1.0
    if main_pressure >= DAILY_SALARY * 1.4:
        contest = 1.25
    elif pressure >= DAILY_SALARY * 1.1:
        contest = 1.15
    elif pressure >= DAILY_SALARY * 0.8:
        contest = 1.05

    bid = base * contest * supply_factor * (0.7 + 0.6 * urgency)

    # If we are in critical HP, push higher but still cap by budget
    if urgency >= 0.8:
        bid = max(bid, DAILY_SALARY * 0.7)

    # Cap bid: never exceed budget
    bid = float(min(my_status['budget'], bid))

    # Add small day-based jitter to avoid ties (deterministic)
    jitter = ((day % 7) - 3) * 0.8
    bid = max(0.0, bid + jitter)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    alive = [o for o in opponents_status.values() if o['alive']]

    # Base bid: fraction of salary depending on supply
    if supply >= 20:
        base_ratio = 0.5
    else:
        base_ratio = 0.65

    # Adjust for low HP
    if hp <= 2:
        base_ratio = 0.9
    elif hp <= 4:
        base_ratio = max(base_ratio, 0.75)

    bid = min(budget, DAILY_SALARY * base_ratio)

    # Use previous day trace if available
    if alive:
        prev_bids = []
        for opp in alive:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
        if prev_bids:
            max_prev = max(prev_bids)
            # If someone bid very high yesterday, they might still be aggressive
            if max_prev >= DAILY_SALARY * 0.85:
                if hp > 3:
                    bid = min(budget, DAILY_SALARY * 0.3)
                else:
                    bid = min(budget, DAILY_SALARY * 0.95)
            else:
                # try to stay just above or at a safe level
                target = max(DAILY_SALARY * 0.4, max_prev + 1.0)
                bid = min(budget, target)

    # Ensure we don't bid more than budget
    return float(bid)
